        return f"Output '{res}' is not a permutation of '{s}'"
    rank = {c: i for i, c in enumerate(order)}
    prev = -1
    for c in res:
        if c in rank:
            if rank[c] < prev:
                return f"Character '{c}' violates custom order '{order}'"
            prev = rank[c]
